mapper.select:
SELECT r.id AS reservationId, s.name AS stationName, r.reservation_type AS reservationType, r.status, rt.start_time AS startTime, rt.end_time AS endTime, rtg.target_kwh AS targetAmount, c.connector_type AS connectorType, em.model_name AS carType FROM reservation r LEFT JOIN reservation_time rt ON r.id = rt.reservation_id LEFT JOIN reservation_target rtg ON r.id = rtg.reservation_id LEFT JOIN user_vehicle uv ON r.user_vehicle_id = uv.id LEFT JOIN ev_model em ON uv.model_id = em.id JOIN charger c ON r.charger_id = c.id JOIN station s ON c.station_id = s.id WHERE r.user_id = #{userId} AND ( /* 🌟 핵심: 취소 건과 완료 건만 지난 예약에 표시 (만료 제외) */ r.status IN ('COMPLETED', 'CANCELED')
/* 🌟 RESERVED 상태였으나 오지 않아서 시간이 지나버린 건들도 지난 예약으로 이동 */
OR (r.status = 'RESERVED' AND rt.end_time < NOW())
) ORDER BY rt.start_time DESC

